import xml.etree.ElementTree as ET
root=ET.fromstring(driver.page_source)
parent={c:p for p in root.iter() for c in p}
rows=[]
for n in root.iter():
    if n.attrib.get('resource-id')=='org.tasks:id/title' and n.attrib.get('text'):
        # climb to nearest ancestor containing exactly one title and a due_date
        a=n
        chosen=None
        for _ in range(6):
            a=parent.get(a)
            if a is None: break
            titles=[x for x in a.iter() if x.attrib.get('resource-id')=='org.tasks:id/title']
            dues=[x for x in a.iter() if x.attrib.get('resource-id')=='org.tasks:id/due_date']
            if len(titles)==1 and dues:
                chosen=a
            elif len(titles)>1:
                break
        if chosen is not None:
            due=next((x.attrib.get('text') for x in chosen.iter() if x.attrib.get('resource-id')=='org.tasks:id/due_date'),None)
            if due=='Wed':
                nodes=[]
                for x in chosen.iter():
                    attrs={k:x.attrib.get(k) for k in ('class','resource-id','text','content-desc','clickable','checkable','checked','selected','bounds') if x.attrib.get(k) not in (None,'','false','null')}
                    if attrs: nodes.append(attrs)
                rows.append({'title':n.attrib.get('text'),'rowClass':chosen.attrib.get('class'),'rowId':chosen.attrib.get('resource-id'),'nodes':nodes})
{'package':driver.current_package,'wednesdayRows':rows[:10]}

